export function hs5f(sequence: string, position: number): readonly number[] {
 return TABLE[sequence.slice(position-2,position+3)] ?? [1,0.25,0.25,0.25,0.25];
}
export function hs5fRate(sequence: string, position: number, alternate?: string): number {
 const row=hs5f(sequence,position); return row[0]*(alternate ? row[1+"ACGT".indexOf(alternate)] ?? 1/3 : 1);
}
